function findHighestParent(a1) -- Line: 1
    if not a1 then
        return nil
    end
    if a1.Parent:FindFirstChild("Owner") then
        return a1.Parent
    end
    if a1.Parent == workspace then
        return nil
    end
    return findHighestParent(a1.Parent)
end

return findHighestParent
